/** Verify generated bytes before exposing ordinary filesystem resources. */
import { open, lstat, mkdir, readdir, rename } from 'node:fs/promises'
import { join } from 'node:path'
import type { MediaKind } from './types.ts'

export interface MediaFile {
  path: string
  kind: MediaKind
  mimeType: string
  extension: string
  bytes: number
  width?: number
  height?: number
}

/** Detect supported media containers independently of Provider-supplied names. */
export async function inspectMedia(path: string, maxBytes: number, expected?: MediaKind): Promise<MediaFile> {
  const stat = await lstat(path)
  if (!stat.isFile() || stat.size === 0 || stat.size > maxBytes) throw new Error('Media output must be a nonempty regular file within the configured byte limit')
  const file = await open(path, 'r')
  const header = Buffer.alloc(64)
  try { await file.read(header, 0, header.length, 0) } finally { await file.close() }
  let type: { kind: MediaKind; mimeType: string; extension: string; width?: number; height?: number } | undefined
  if (header.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) && stat.size >= 33) {
    type = { kind: 'image', mimeType: 'image/png', extension: 'png', width: header.readUInt32BE(16), height: header.readUInt32BE(20) }
  } else if (header[0] === 0xff && header[1] === 0xd8 && header[2] === 0xff) type = { kind: 'image', mimeType: 'image/jpeg', extension: 'jpg' }
  else if (header.toString('ascii', 0, 3) === 'GIF') type = { kind: 'image', mimeType: 'image/gif', extension: 'gif' }
  else if (header.toString('ascii', 0, 4) === 'RIFF' && header.toString('ascii', 8, 12) === 'WEBP') type = { kind: 'image', mimeType: 'image/webp', extension: 'webp' }
  else if (header.toString('ascii', 0, 4) === 'RIFF' && header.toString('ascii', 8, 12) === 'WAVE') type = { kind: 'audio', mimeType: 'audio/wav', extension: 'wav' }
  else if (header[0] === 0xff && ((header[1] ?? 0) & 0xf6) === 0xf0) type = { kind: 'audio', mimeType: 'audio/aac', extension: 'aac' }
  else if (header.toString('ascii', 0, 3) === 'ID3' || (header[0] === 0xff && ((header[1] ?? 0) & 0xe0) === 0xe0)) type = { kind: 'audio', mimeType: 'audio/mpeg', extension: 'mp3' }
  else if (header.toString('ascii', 0, 4) === 'fLaC') type = { kind: 'audio', mimeType: 'audio/flac', extension: 'flac' }
  else if (header.toString('ascii', 0, 4) === 'OggS') type = { kind: 'audio', mimeType: 'audio/ogg', extension: 'ogg' }
  else if (header.toString('ascii', 4, 8) === 'ftyp' && !['avif', 'heic', 'heif'].includes(header.toString('ascii', 8, 12))) {
    const audio = expected === 'audio' || ['M4A ', 'M4B '].includes(header.toString('ascii', 8, 12))
    type = audio ? { kind: 'audio', mimeType: 'audio/mp4', extension: 'm4a' } : { kind: 'video', mimeType: 'video/mp4', extension: 'mp4' }
  } else if (header.subarray(0, 4).equals(Buffer.from([0x1a, 0x45, 0xdf, 0xa3]))) {
    type = expected === 'audio' ? { kind: 'audio', mimeType: 'audio/webm', extension: 'webm' } : { kind: 'video', mimeType: 'video/webm', extension: 'webm' }
  }
  if (type === undefined || (expected !== undefined && type.kind !== expected)) throw new Error('Provider returned unsupported media or a different media type')
  return { path, bytes: stat.size, ...type }
}

/** Recover an imported file after a crash between its rename and the job record update. */
export async function existingOutput(
  directory: string, assetId: string, kind: MediaKind, maxBytes: number,
): Promise<MediaFile | undefined> {
  const names = await readdir(directory)
  const name = names.find(value => value.startsWith(`${assetId}.`) && !value.endsWith('.partial'))
  return name === undefined ? undefined : inspectMedia(join(directory, name), maxBytes, kind)
}

/** Commit verified bytes into the job-owned output directory. */
export async function importOutput(
  staging: string, directory: string, assetId: string, kind: MediaKind, maxBytes: number,
): Promise<MediaFile> {
  const media = await inspectMedia(staging, maxBytes, kind)
  await mkdir(directory, { recursive: true })
  const file = await open(staging, 'r+')
  try { await file.sync() } finally { await file.close() }
  const path = join(directory, `${assetId}.${media.extension}`)
  await rename(staging, path)
  return { ...media, path }
}
